package br.com.folha.notes;
import java.util.*;
public class PaperTest {
 public static void main(String[] args){StringBuilder out=new StringBuilder("[");for(String t:Paper.IDS){int w=Paper.width(t),h=Paper.height(t);if(t.equals("genko400")&&w<h)throw new AssertionError("400-character manuscript must be landscape");List<float[]> lines=Paper.lines(w,h,t);for(float[] l:lines)if(l[0]<0||l[1]<0||l[2]>w+.01||l[3]>h+.01)throw new AssertionError("Paper guide exceeds page: "+t);if(t.equals("genko200")&&lines.stream().filter(l->l[4]==0&&l[1]==l[3]).count()!=210)throw new AssertionError("200 manuscript missing cells");if(t.equals("genko400")&&lines.stream().filter(l->l[4]==0&&l[1]==l[3]).count()!=420)throw new AssertionError("400 manuscript missing cells");if(out.length()>1)out.append(',');out.append("{\"id\":\"").append(t).append("\",\"width\":").append(w).append(",\"height\":").append(h).append(",\"lines\":[");for(int i=0;i<lines.size();i++){if(i>0)out.append(',');out.append(Arrays.toString(lines.get(i)));}out.append("]}");}if(args.length>0)System.out.println("21 paper models passed: bounds, 200/400 manuscript cells and landscape aspect.");else System.out.print(out.append(']'));}
}
